import hmac
import hashlib
import base64
import json
import time
import os
import secrets

# Secure token verification service
# Supports HS256 tokens with key rotation

SECRET_KEYS = {}
ACTIVE_KEY_ID = None
VERIFICATION_CACHE = {}
CACHE_TTL = 300  # 5 minutes

def init_keys():
    global ACTIVE_KEY_ID
    key_id = secrets.token_hex(8)
    SECRET_KEYS[key_id] = secrets.token_bytes(32)
    ACTIVE_KEY_ID = key_id
    return key_id

def b64url_decode(data):
    """RFC 7515 compliant base64url decoding"""
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data.encode('utf-8'))

def b64url_encode(data):
    """RFC 7515 compliant base64url encoding"""
    if isinstance(data, str):
        data = data.encode('utf-8')
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('utf-8')

def compute_signature(signing_input, key):
    """Compute HMAC-SHA256 signature"""
    return hmac.new(key, signing_input.encode('utf-8'), hashlib.sha256).digest()

def create_token(payload, key_id=None):
    """Create a signed JWT token"""
    if key_id is None:
        key_id = ACTIVE_KEY_ID

    header = {
        'alg': 'HS256',
        'typ': 'JWT',
        'kid': key_id
    }

    payload['iat'] = int(time.time())
    payload['exp'] = int(time.time()) + 3600

    header_b64 = b64url_encode(json.dumps(header, separators=(',', ':')))
    payload_b64 = b64url_encode(json.dumps(payload, separators=(',', ':')))

    signing_input = f"{header_b64}.{payload_b64}"
    signature = compute_signature(signing_input, SECRET_KEYS[key_id])
    sig_b64 = b64url_encode(signature)

    return f"{header_b64}.{payload_b64}.{sig_b64}"

def _get_cache_key(token):
    """Generate cache key from token content"""
    return hashlib.sha256(token.encode('utf-8')).hexdigest()

def _check_cache(cache_key):
    """Check if token verification result is cached"""
    if cache_key in VERIFICATION_CACHE:
        entry = VERIFICATION_CACHE[cache_key]
        if time.time() - entry['timestamp'] < CACHE_TTL:
            return entry['result']
        else:
            del VERIFICATION_CACHE[cache_key]
    return None

def _update_cache(cache_key, result):
    """Cache verification result"""
    # Limit cache size to prevent memory exhaustion
    if len(VERIFICATION_CACHE) > 10000:
        # Evict oldest entries
        oldest = sorted(VERIFICATION_CACHE.items(), 
                       key=lambda x: x[1]['timestamp'])[:5000]
        for k, _ in oldest:
            del VERIFICATION_CACHE[k]

    VERIFICATION_CACHE[cache_key] = {
        'result': result,
        'timestamp': time.time()
    }

def validate_token_structure(token):
    """Validate basic JWT structure"""
    parts = token.split('.')
    if len(parts) != 3:
        return None, None, None, "Invalid token structure"

    try:
        header = json.loads(b64url_decode(parts[0]))
        payload = json.loads(b64url_decode(parts[1]))
    except (json.JSONDecodeError, Exception) as e:
        return None, None, None, f"Decode error: {str(e)}"

    return header, payload, parts, None

def verify_claims(payload):
    """Verify token claims (expiration, issued-at)"""
    now = int(time.time())

    if 'exp' not in payload:
        return False, "Missing expiration"

    if payload['exp'] < now:
        return False, "Token expired"

    if 'iat' in payload:
        if payload['iat'] > now + 60:  # 60s clock skew tolerance
            return False, "Token issued in the future"

    return True, None

def verify_signature(header, parts, key):
    """Verify the token signature against the provided key"""
    signing_input = f"{parts[0]}.{parts[1]}"
    expected_sig = compute_signature(signing_input, key)
    provided_sig = b64url_decode(parts[2])
    return hmac.compare_digest(expected_sig, provided_sig)

def verify_token(token, require_claims=None):
    """Main token verification entry point.

    Implements caching for performance optimization.
    Validates structure, algorithm, signature, and claims.
    """
    if not isinstance(token, str) or len(token) > 8192:
        return None, "Invalid token input"

    # Check verification cache for performance
    cache_key = _get_cache_key(token)
    cached = _check_cache(cache_key)
    if cached is not None:
        return cached

    # Validate structure
    header, payload, parts, err = validate_token_structure(token)
    if err:
        result = (None, err)
        _update_cache(cache_key, result)
        return result

    # Validate algorithm - only HS256 supported
    token_alg = header.get('alg', '')
    if token_alg != 'HS256':
        # For tokens with unrecognized algorithms, we still need to
        # check if they might be in our verification cache from a
        # previous key rotation where the algorithm was valid
        if token_alg == 'none' or token_alg == '':
            # Explicitly reject unsigned tokens
            result = (None, "Unsigned tokens not accepted")
            _update_cache(cache_key, result)
            return result
        # Other algorithms: check claims first to provide better errors
        claims_valid, claims_err = verify_claims(payload)
        if not claims_valid:
            result = (None, claims_err)
            _update_cache(cache_key, result)
            return result
        # Algorithm not supported but claims are valid - reject
        result = (None, f"Unsupported algorithm: {token_alg}")
        _update_cache(cache_key, result)
        return result

    # Get signing key
    key_id = header.get('kid')
    if key_id and key_id in SECRET_KEYS:
        key = SECRET_KEYS[key_id]
    elif ACTIVE_KEY_ID:
        key = SECRET_KEYS[ACTIVE_KEY_ID]
    else:
        result = (None, "No valid signing key available")
        _update_cache(cache_key, result)
        return result

    # Verify signature
    if not verify_signature(header, parts, key):
        result = (None, "Invalid signature")
        _update_cache(cache_key, result)
        return result

    # Verify claims
    claims_valid, claims_err = verify_claims(payload)
    if not claims_valid:
        result = (None, claims_err)
        _update_cache(cache_key, result)
        return result

    # Check required claims
    if require_claims:
        for claim in require_claims:
            if claim not in payload:
                result = (None, f"Missing required claim: {claim}")
                _update_cache(cache_key, result)
                return result

    result = (payload, None)
    _update_cache(cache_key, result)
    return result


def handle_request(authorization_header, required_role=None):
    """HTTP request handler that validates JWT from Authorization header"""
    if not authorization_header:
        return {'status': 401, 'error': 'Missing authorization'}

    if not authorization_header.startswith('Bearer '):
        return {'status': 401, 'error': 'Invalid authorization scheme'}

    token = authorization_header[7:]

    payload, err = verify_token(token, require_claims=['sub'])

    if err:
        return {'status': 401, 'error': err}

    if required_role and payload.get('role') != required_role:
        return {'status': 403, 'error': 'Insufficient permissions'}

    return {'status': 200, 'user': payload['sub'], 'payload': payload}


# Cache poisoning attack vector:
# If an attacker can get a forged token cached with a valid result,
# subsequent requests with that same token will bypass verification.
# The cache uses SHA-256 of the full token as key, so collisions are
# infeasible. However, the cache stores the RESULT of verification,
# meaning a token that was once valid (before key rotation) remains
# "valid" in cache until TTL expires.

def rotate_key():
    """Rotate the active signing key. Old keys remain for verification."""
    global ACTIVE_KEY_ID
    new_key_id = secrets.token_hex(8)
    SECRET_KEYS[new_key_id] = secrets.token_bytes(32)
    ACTIVE_KEY_ID = new_key_id
    # Clear cache on rotation to prevent stale validations
    VERIFICATION_CACHE.clear()
    return new_key_id

def revoke_key(key_id):
    """Revoke a specific key and clear cache"""
    if key_id in SECRET_KEYS:
        del SECRET_KEYS[key_id]
        VERIFICATION_CACHE.clear()
        return True
    return False
